/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: expectPrivate, applyReviewedTrackArtist, call
 *   Constants: artistId, labelId, reviewedId, ids, flags, previous
 *   Variables: harness, server, base, userToken, adminToken, reviewedArtist
 * Tests
 *   - no listener, legacy, Search, Page, Follow, Library or Playlist response carries a MusicBrainz ID, for any caller
 * @end-catalog */

/**
 * MusicBrainz IDs are private import provenance: an Artist and a label Organization that keep one, credited on an Album and its
 * Track, followed, saved to the Library, placed in a playlist and in a Home artist carousel, and an Artist an applied
 * existing-Album review created with the ID lookup found for its Track, never show the key or the ID value in any listener v1,
 * legacy content (including the Track list, Page list and expanded Library page), Search, Follow, Page, Library or Playlist
 * response, for an anonymous caller, a listener or an administrator in User view (listener routes are role-independent). Room
 * responses are scanned in test/rooms/roomMediaDiscovery.integration.ts. All names, IDs and accounts are synthetic.
 */
import assert from 'node:assert/strict';
import { randomUUID } from 'node:crypto';
import type { Server } from 'node:http';
import os from 'node:os';
import path from 'node:path';
import { after, before, test } from 'node:test';
import { ObjectId } from 'mongodb';
import { createApp } from '../../src/app';
import { getDb } from '../../src/infrastructure/database';
import { createSession } from '../../src/services/auth/authSessionService';
import { adminCatalogItemRevision } from '../../src/administration/catalog/adminCatalogService';
import { createCatalogReview, getCatalogReview } from '../../src/administration/catalog/adminCatalogReviewService';
import { applyCatalogReview, getCatalogReviewCandidates } from '../../src/administration/catalog/adminCatalogReviewApply';
import { adminImportIndexes, initializeAdminImportStorage } from '../../src/administration/import/adminImportService';
import { resolveCatalogReviewLookup, submitCatalogReviewLookup } from '../../src/administration/lookup/catalogReviewLookupRequests';
import { startMongoReplicaSet, type MongoReplicaSetHarness } from '../support/mongoReplicaSet';
import { creditedRelease, drainLookup, lookupContact, reviewSearch } from '../support/catalogReviewRunFixtures';

const artistId = '00000000-0000-4000-8000-0000000000f1', labelId = '00000000-0000-4000-8000-0000000000f2', reviewedId = '00000000-0000-4000-8000-0000000000f3';
const ids = { user: new ObjectId(), admin: new ObjectId(), artist: new ObjectId(), label: new ObjectId(), album: new ObjectId(), track: new ObjectId(), carousel: new ObjectId(), placement: new ObjectId() };
const flags = { FINITUDE_ARTIST_FOLLOWS_ENABLED: 'true', FINITUDE_ADMIN_IMPORTS_ENABLED: 'true', FINITUDE_ADMIN_METADATA_LOOKUP_CONTACT: lookupContact };
const previous = Object.fromEntries(Object.keys(flags).map(key => [key, process.env[key]]));
let harness: MongoReplicaSetHarness, server: Server, base = '', userToken = '', adminToken = '', reviewedArtist = '';

/** Fails when a payload carries the MusicBrainz ID key anywhere or any of the three ID values. */
function expectPrivate(label: string, payload: unknown) {
    const text = JSON.stringify(payload);
    assert.equal(text.includes('musicBrainzId'), false, `${label} exposed the musicBrainzId key`);
    for (const value of [artistId, labelId, reviewedId]) assert.equal(text.includes(value), false, `${label} exposed a MusicBrainz ID`);
}
/**
 * Reviews the Album against a release whose Track also credits a singer lookup found under `reviewedId`, and applies that member's
 * Artist entries, which creates the singer's Artist with that ID; returns the new Artist's ID.
 */
async function applyReviewedTrackArtist(): Promise<string> {
    const db = getDb()!, actor = ids.admin.toHexString(), release = '00000000-0000-4000-8000-0000000000e1';
    for (const index of adminImportIndexes) await db.collection(index.collection).createIndex(index.keys, index.options);
    await initializeAdminImportStorage(db);
    const created = await createCatalogReview(actor, { operationId: randomUUID(), albumId: ids.album.toHexString(),
        expectedRevision: adminCatalogItemRevision('album', await db.collection('albums').findOne({ _id: ids.album })), another: true });
    const id = created.item.id, slotId = created.item.source.tracks[0].slotId;
    await submitCatalogReviewLookup(actor, id, { operationId: randomUUID(), expectedRevision: created.item.revision, kind: 'album', text: 'Private Provenance Album' });
    await drainLookup([reviewSearch({ release: 'Private Provenance Album', artist: 'Private Provenance Artist' }, [[release, 1]]), reviewSearch({ release: 'Private Provenance Album' }, [[release, 1]]),
        ...creditedRelease(release, { releaseArtists: [[artistId, 'Private Provenance Artist']], label: [labelId, 'Private Provenance Label'],
            tracks: [[[artistId, 'Private Provenance Artist'], [reviewedId, 'Reviewed Provenance Singer']]], lengths: [190_000] })]);
    // The member's saved list differs from its track's credit: answered with lookup, then applied with what the confirmation shows.
    let review = await getCatalogReview(actor, id);
    const path = `tracks.${slotId}.artists`, base = review.item.draft.tracks[0].artists;
    await resolveCatalogReviewLookup(actor, id, { operationId: randomUUID(), expectedRevision: review.item.revision, run: 1, candidateKey: `musicbrainz:${release}`, answers: [{ path, answer: 'lookup', base }] });
    const shown = await getCatalogReviewCandidates(actor, id);
    review = await getCatalogReview(actor, id);
    await applyCatalogReview(actor, id, { operationId: randomUUID(), expectedRevision: review.item.revision, fields: [], memberCredits: [slotId], preselections: shown.preselections,
        musicBrainzIds: shown.musicBrainzIds, expectedValueRevision: shown.valueRevision });
    const singer = await db.collection('artists').findOne({ name: 'Reviewed Provenance Singer' });
    assert.equal(singer?.musicBrainzId, reviewedId);
    return singer!._id.toHexString();
}
const call = (route: string, token = '', method = 'GET', body?: unknown, headers: Record<string, string> = {}) => fetch(base + route, {
    method, headers: { ...(token ? { Authorization: `Bearer ${token}` } : {}), ...(body === undefined ? {} : { 'Content-Type': 'application/json' }), ...headers },
    ...(body === undefined ? {} : { body: JSON.stringify(body) })
});

before(async () => {
    Object.assign(process.env, flags);
    harness = await startMongoReplicaSet('archtree-musicbrainz-privacy-test');
    const db = getDb()!, credit = (subjectType: string, subjectId: ObjectId, role: string, order: number) => ({ creditId: `credit_${role}_${order}`, subjectType, subjectId: subjectId.toHexString(), role, order });
    const user = { _id: ids.user, email: 'privacy-listener@example.test', role: 'user', emailVerified: true };
    const admin = { _id: ids.admin, email: 'privacy-admin@example.test', role: 'admin', emailVerified: true };
    await db.collection('users').insertMany([user, admin]);
    await db.collection('artists').insertOne({ _id: ids.artist, name: 'Private Provenance Artist', bio: 'Synthetic biography', coverArtUrl: '', albumIds: [ids.album.toHexString()], lifecycleStatus: 'ready', musicBrainzId: artistId });
    await db.collection('organizations').insertOne({ _id: ids.label, name: 'Private Provenance Label', organizationType: 'label', description: '', lifecycleStatus: 'ready', musicBrainzId: labelId });
    await db.collection('albums').insertOne({ _id: ids.album, title: 'Private Provenance Album', coverArtUrl: '', audioTrackIds: [ids.track.toHexString()], releaseDate: { year: 2026 }, lifecycleStatus: 'ready',
        credits: [credit('artist', ids.artist, 'primary', 0), credit('organization', ids.label, 'label', 1)], attributionStatus: 'documented', creditRevision: 1 });
    await db.collection('audioTracks').insertOne({ _id: ids.track, title: 'Private Provenance Track', artistIds: [ids.artist.toHexString()], albumId: ids.album.toHexString(), duration: '03:10', coverArtUrl: '',
        mediaType: 'audio', uploadStatus: 'ready', publicationStatus: 'ready', s3Key: ids.track.toHexString(), credits: [credit('artist', ids.artist, 'primary', 0)], attributionStatus: 'documented', creditRevision: 1 });
    await db.collection('carousels').insertOne({ _id: ids.carousel, name: 'Artist Tracks', mode: 'artist', items: [], artistConfig: { artistId: ids.artist.toHexString(), contentType: 'audioTrack', sort: 'titleAsc', limit: 5 } });
    await db.collection('pages').insertMany([{ slug: 'home', title: 'Listen Now', items: [{ itemId: ids.placement.toHexString(), itemType: 'carousel', carouselId: ids.carousel.toHexString(), order: 0 }] },
        { slug: 'library', title: 'Library', items: [{ itemId: new ObjectId().toHexString(), itemType: 'carousel', carouselId: ids.carousel.toHexString(), order: 0 }] }]);
    userToken = (await createSession(user)).accessToken; adminToken = (await createSession(admin)).accessToken;
    reviewedArtist = await applyReviewedTrackArtist();
    const app = createApp({ listenerDistPath: path.join(os.tmpdir(), 'archtree-musicbrainz-privacy-missing') });
    server = await new Promise(resolve => { const listening = app.listen(0, '127.0.0.1', () => resolve(listening)); });
    const address = server.address(); assert.ok(address && typeof address !== 'string'); base = `http://127.0.0.1:${address.port}`;
});
after(async () => {
    await new Promise<void>(resolve => server ? server.close(() => resolve()) : resolve()); await harness?.stop();
    for (const [key, value] of Object.entries(previous)) { if (value === undefined) delete process.env[key]; else process.env[key] = value; }
});

test('no listener, legacy, Search, Page, Follow, Library or Playlist response carries a MusicBrainz ID, for any caller', async () => {
    const album = ids.album.toHexString(), track = ids.track.toHexString(), artist = ids.artist.toHexString(), label = ids.label.toHexString();
    // The listener follows the Artist, saves the Album and adds the Track to a playlist; each response is checked too.
    for (const token of [userToken, adminToken]) {
        const follow = await call(`/content/me/artist-follows/${artist}`, token, 'PUT', {});
        assert.ok(follow.status < 300, `follow ${follow.status}`); expectPrivate('follow', await follow.json());
        const status = await call('/content/me/artist-follows/status', token, 'POST', { artistIds: [artist] });
        expectPrivate('follow status', await status.text());
        const save = await call(`/content/me/saves/album/${album}`, token, 'PUT', {});
        assert.ok(save.status < 300, `save ${save.status}`); expectPrivate('save', await save.text());
    }
    const created = await call('/content/me/playlists', userToken, 'POST', { name: 'Synthetic Playlist' }, { 'Idempotency-Key': 'privacy-playlist-create' });
    assert.ok(created.status < 300, `playlist ${created.status}`);
    const playlistBody: any = await created.json(); expectPrivate('playlist create', playlistBody);
    const playlist = playlistBody.playlist?.id ?? playlistBody.id;
    assert.ok(playlist, JSON.stringify(playlistBody));
    const added = await call(`/content/me/playlists/${playlist}/items`, userToken, 'POST', { audioTrackId: track },
        { 'Idempotency-Key': 'privacy-playlist-add', 'If-Match': created.headers.get('etag') ?? `"${playlistBody.playlist?.revision ?? playlistBody.revision ?? 1}"` });
    assert.ok(added.status < 300, `playlist add ${added.status}`);
    expectPrivate('playlist add', await added.text());

    const listener = ['/api/listener/v1/home', '/api/listener/v1/search?q=Private', `/api/listener/v1/albums/${album}`, `/api/listener/v1/artists/${artist}`,
        `/api/listener/v1/organizations/${label}`, `/api/listener/v1/tracks/${track}`, `/api/listener/v1/pages/home/items/${ids.placement.toHexString()}`,
        `/api/listener/v1/artists/${reviewedArtist}`, '/api/listener/v1/search?q=Reviewed'];
    // `/content/audioTrack/:id` only redirects to the audio stream, so it carries no metadata to scan.
    const legacy = ['/content/artists', `/content/artist/${artist}`, `/content/artist/${reviewedArtist}`, `/content/organization/${label}`, '/content/albums', `/content/album/${album}`, '/content/audioTracks',
        '/content/search?query=Private', '/content/search?q=Private', '/content/pages', '/content/pages/home', '/content/pages/home/expanded'];
    const personal = ['/api/listener/v1/library', '/api/listener/v1/recently-played', '/content/me/library', '/content/me/playlists', `/content/me/playlists/${playlist}`,
        '/content/pages/library/expanded'];
    let checked = 0;
    for (const [label, token] of [['anonymous', ''], ['listener', userToken], ['administrator in User view', adminToken]] as const) {
        for (const route of [...listener, ...legacy, ...(token ? personal : [])]) {
            const response = await call(route, token);
            const text = await response.text();
            expectPrivate(`${label} ${route}`, text);
            if (response.status === 200) checked++;
        }
    }
    // The catalog routes answered, so the scan read real payloads that name the Artist, the label and their releases.
    const albumView: any = await (await call(`/api/listener/v1/albums/${album}`)).json();
    assert.match(JSON.stringify(albumView), /Private Provenance Artist/);
    assert.match(JSON.stringify(albumView), /Private Provenance Label/);
    assert.match(JSON.stringify(await (await call(`/content/artist/${artist}`)).json()), /Private Provenance Artist/);
    // The Artist the review created is credited on the Track and found by Search, so its responses were scanned too.
    assert.match(JSON.stringify(await (await call(`/api/listener/v1/tracks/${track}`)).json()), /Reviewed Provenance Singer/);
    assert.match(JSON.stringify(await (await call('/api/listener/v1/search?q=Reviewed')).json()), /Reviewed Provenance Singer/);
    for (const route of [`/api/listener/v1/artists/${reviewedArtist}`, `/content/artist/${reviewedArtist}`]) assert.match(await (await call(route)).text(), /Reviewed Provenance Singer/, route);
    assert.ok(checked >= 63, `only ${checked} responses answered 200`);
});
